 if(process.argv.includes('--profile'))await send('Page.addScriptToEvaluateOnNewDocument',{source:`window.__perf={frames:[],draws:0,triangles:0,uploads:0,start:0};for(const key of ['drawElements','clear','texSubImage2D']){const original=WebGLRenderingContext.prototype[key];WebGLRenderingContext.prototype[key]=function(...args){const p=window.__perf;if(key==='drawElements'){p.draws++;p.triangles+=args[1]/3;}if(key==='clear'&&!p.start)p.start=performance.now();if(key==='texSubImage2D'){const c=args[args.length-1];p.uploads+=(c?.width||0)*(c?.height||0)*4;}return original.apply(this,args);};}window.addEventListener('gobhi:frame',()=>{const p=window.__perf;p.frames.push({ms:performance.now()-p.start,draws:p.draws,triangles:p.triangles,uploads:p.uploads});p.draws=p.triangles=p.uploads=p.start=0;});`});
